import{_ as t,o as s,c as a,ag as i}from"./chunks/framework.CrXGS008.js";const k=JSON.parse('{"title":"Vertical Slice: Outbound Webhooks","description":"","frontmatter":{},"headers":[],"relativePath":"en/12-outbound-webhooks.md","filePath":"en/12-outbound-webhooks.md"}'),n={name:"en/12-outbound-webhooks.md"};function o(r,e,l,d,c,p){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="vertical-slice-outbound-webhooks" tabindex="-1">Vertical Slice: Outbound Webhooks <a class="header-anchor" href="#vertical-slice-outbound-webhooks" aria-label="Permalink to &quot;Vertical Slice: Outbound Webhooks&quot;">​</a></h1><blockquote><p><strong>Decoupled event dispatching via Arq Worker, HMAC-SHA256 signature verification, and delivery logging.</strong></p></blockquote><hr><h2 id="_1-architectural-overview" tabindex="-1">1. Architectural Overview <a class="header-anchor" href="#_1-architectural-overview" aria-label="Permalink to &quot;1. Architectural Overview&quot;">​</a></h2><p>The <code>webhooks</code> slice (<code>apps/api/src/slices/webhooks/</code>) enables third-party integration capabilities for workspaces in SoftForge:</p><ul><li><strong>Decoupled Asynchronous Dispatch:</strong> When an event occurs (e.g., project created, member invited, invoice paid), the API logs a <code>pending</code> delivery row and delegates HTTP transmission to the Arq Worker, keeping web API latency minimal (&lt; 15ms).</li><li><strong>HMAC-SHA256 Signatures:</strong> Every endpoint generates a secret key (<code>whsec_...</code>). Outbound requests include <code>X-SoftForge-Signature: t={timestamp},v1={hex_digest}</code> preventing payload tampering and replay attacks.</li><li><strong>Granular Event Filtering:</strong> Webhook endpoints can subscribe to specific events (e.g. <code>[&quot;project.created&quot;]</code>) or use wildcard <code>[&quot;*&quot;]</code> for all events.</li><li><strong>Comprehensive Delivery Logs:</strong> The <code>webhook_deliveries</code> table tracks HTTP status codes, initial response body characters, timestamps, retry counts, and error traces.</li><li><strong>Offline &amp; Mock Testing:</strong> Endpoints configured with <code>mock://</code> urls are processed locally by the worker in milliseconds without external HTTP requests.</li></ul><hr><h2 id="_2-sequence-diagram" tabindex="-1">2. Sequence Diagram <a class="header-anchor" href="#_2-sequence-diagram" aria-label="Permalink to &quot;2. Sequence Diagram&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    autonumber</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    actor Client as User / Frontend</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant API as SoftForge API (/projects)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant DB as PostgreSQL Database</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant Redis as Redis 7 (Arq Queue)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant Worker as Background Worker</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    actor Receiver as Customer External Server</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Client-&gt;&gt;API: POST /api/v1/workspaces/{id}/projects</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    API-&gt;&gt;API: Creates project</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    API-&gt;&gt;DB: Creates delivery record (status=&#39;pending&#39;)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    API-&gt;&gt;Redis: Enqueues &quot;dispatch_webhook_task&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    API--&gt;&gt;Client: HTTP 201 Created (Instantaneous)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over Worker,Receiver: Background worker dispatch</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Worker-&gt;&gt;Redis: Pops delivery job</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Worker-&gt;&gt;Worker: Computes HMAC-SHA256 signature</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Worker-&gt;&gt;Receiver: POST payload with X-SoftForge-* headers</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Receiver--&gt;&gt;Worker: HTTP 200 OK</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Worker-&gt;&gt;DB: Updates delivery (status=&#39;success&#39;)</span></span></code></pre></div><hr><h2 id="_3-endpoints" tabindex="-1">3. Endpoints <a class="header-anchor" href="#_3-endpoints" aria-label="Permalink to &quot;3. Endpoints&quot;">​</a></h2><p>Requires Administrator or Owner permissions (<code>WorkspaceRole.ADMIN</code>):</p><table tabindex="0"><thead><tr><th style="text-align:left;">Method</th><th style="text-align:left;">Endpoint</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>POST</code></td><td style="text-align:left;"><code>/api/v1/workspaces/{id}/webhooks</code></td><td style="text-align:left;">Registers new endpoint and creates <code>whsec_</code> secret</td></tr><tr><td style="text-align:left;"><code>GET</code></td><td style="text-align:left;"><code>/api/v1/workspaces/{id}/webhooks</code></td><td style="text-align:left;">Lists all workspace webhooks</td></tr><tr><td style="text-align:left;"><code>GET</code></td><td style="text-align:left;"><code>/api/v1/workspaces/{id}/webhooks/{endpoint_id}</code></td><td style="text-align:left;">Retrieves webhook details</td></tr><tr><td style="text-align:left;"><code>PATCH</code></td><td style="text-align:left;"><code>/api/v1/workspaces/{id}/webhooks/{endpoint_id}</code></td><td style="text-align:left;">Updates URL, subscribed events, or active status</td></tr><tr><td style="text-align:left;"><code>DELETE</code></td><td style="text-align:left;"><code>/api/v1/workspaces/{id}/webhooks/{endpoint_id}</code></td><td style="text-align:left;">Deletes webhook and associated delivery logs</td></tr><tr><td style="text-align:left;"><code>GET</code></td><td style="text-align:left;"><code>/api/v1/workspaces/{id}/webhooks/{endpoint_id}/deliveries</code></td><td style="text-align:left;">Paginated delivery history</td></tr></tbody></table>`,13)])])}const g=t(n,[["render",o]]);export{k as __pageData,g as default};
